        "StopMappingMessage",
        "SubmitMapMessage",
        "DetectionsMessage",
        "ImuSample",
        "ImuBatchMessage",
        "ExposureStats",
        "ExposureReportMessage",
        "GetStatusMessage",
        "GetPatternMessage",
        "GetLiveMapMessage",
